import './Registrar_Empresa.css'
import React, { useState } from "react";


//!importar imagens 
import imgUsuario  from '../Login_User/img/iconos/usuario.png'
import imgCorreo from '../Login_User/img/iconos/gmail.png'
import imgClave from '../Login_User/img/iconos/contrasena.png'
import imgver from '../Login_User/img/iconos/ojo-con-pestanas-black.png'
import imgocultar from '../Login_User/img/iconos/cerrar-ojo-black.png'



const RegistrarEmpresa = ({ setView }) => {
  const [contactName, setContactName] = useState("");
  const [email, setEmail] = useState("");
  const [ver, setVer] = useState(false)

                        
                        


  
  const handleContactNameChange = (e) => {
    setContactName(e.target.value);
  };

  const handleEmailChange = (e) => {
    setEmail(e.target.value);
  };

  const HandleVer = ()=>{
    setVer(!ver)
  }

  const handleEnviarUser = () =>{
    alert("Funciona")
  }



  return (
    <div className="body-Empresa-register">
      <h1 className='Titulos'>Registrar Empresa</h1>
      
        <div className="Register-container-input">
          
          <div className="input-group-empresa">
            <img src={imgUsuario} alt='Nombre Usuario'/>
            <input
              
              name="contactName"
              placeholder="Nombre Propietario"
              
              type="text"
              value={contactName}
              onChange={handleContactNameChange}
              required
            />
            
          </div>
        </div>
        <div className="Register-container-input">
         
          <div className="input-group-empresa">
          <img src={imgCorreo} alt='Nombre Usuario'/>
            <input
             
              name="email"
              placeholder="Correo Empresa"
              
              type="email"
              value={email}
              onChange={handleEmailChange}
              required
            />
           
          </div>
        </div>
        <div className="Register-container-input">
         
          <div className="input-group-empresa">
          <img src={imgClave} alt='Nombre Usuario'/>
            <input
              
              name="email"
              placeholder="Clave"
             
              type={
                ver
                ?"text"
                :"password"}
              value={email}
              onChange={handleEmailChange}
              required
            />
            <img src={
                        ver
                        ?imgver
                        :imgocultar} alt='Nombre Usuario' onClick={HandleVer}/>
           
          </div>
         
        </div>


        <div className="Register-container-input">
         
         <div className="input-group-empresa">
         
           <input
             
             name="email"
             placeholder="Repetir Clave"
             
             type={
                ver
                ?"text"
                :"password"}
             value={email}
             onChange={handleEmailChange}
             required
           />
          
         </div>
        
       </div>
        
       <div onClick={handleEnviarUser} className='btn-Enviar'>Iniciar sesión</div>
   
      <div className="btn-regresar" onClick={() => setView("login")}>Regresar</div>
    </div>
  );
}

export default RegistrarEmpresa;
